<section class="page-header"><div><h1><?= htmlspecialchars($board["name"] ?? "") ?></h1><p><?= htmlspecialchars($board["description"] ?? "") ?></p></div><a class="button secondary" href="/boards">Back to boards</a></section>
<section class="card"><h2>Board Information</h2><div class="metric-list"><div class="metric-row"><strong>ID</strong><span><?= htmlspecialchars($board["id"] ?? "") ?></span></div><div class="metric-row"><strong>Status</strong><span class="badge badge-info"><?= htmlspecialchars(ucfirst($board["status"] ?? "")) ?></span></div><div class="metric-row"><strong>Subjects</strong><span><?= count($board["subjects"] ?? []) ?></span></div></div></section>
<section class="card"><h2>Subjects</h2><?php if (empty($board["subjects"])): ?><div class="empty-state">No subjects have been added yet.</div><?php else: ?><div class="record-list"><?php foreach ($board["subjects"] as $subject): ?><a class="record-card card" href="/subject/view?id=<?= urlencode($subject["id"] ?? "") ?>"><?= htmlspecialchars($subject["name"] ?? $subject["code"] ?? $subject["id"] ?? "") ?></a><?php endforeach; ?></div><?php endif; ?><p><a href="/subject/create?board=<?= urlencode($board["id"] ?? "") ?>">Add Subject</a></p></section>
